    public List<Class<? extends PsiElement>> getApplicablePsiTypes() {
        return Collections.singletonList(PsiClass.class);
    }

    @Override
    public JavaElementVisitor createPsiVisitor(@NonNull JavaContext context) {
        return new HandlerVisitor(context);
    }

    private static class HandlerVisitor extends JavaElementVisitor {
        private final JavaContext mContext;

        public HandlerVisitor(JavaContext context) {
            mContext = context;
        }

        @Override
        public void visitClass(PsiClass aClass) {
            super.visitClass(aClass);

            if (!isNonStaticInnerHandler(aClass)) {
                return;
            }

            // If the class extends Handler and is non-static inner class, it might leak.
            // However, if the Handler is associated with a non-main Looper, it's fine.
            if (hasNonMainLooper(aClass)) {
                return;
            }

            mContext.report(ISSUE, aClass, mContext.getNameLocation(aClass),
                "This Handler class should be static or leaks might occur (anonymous android.os.Handler)");
        }

        private boolean isNonStaticInnerHandler(PsiClass aClass) {
            if (aClass.hasModifierProperty(PsiModifier.STATIC)) {
                return false;
            }

            return mContext.getEvaluator().extendsClass(aClass, "android.os.Handler", false);
        }

        private boolean hasNonMainLooper(PsiClass aClass) {
            // Check all constructors
            for (PsiMethod constructor : aClass.getConstructors()) {
                PsiMethodCallExpression[] calls = PsiTreeUtil.getChildrenOfType(constructor,
                        PsiMethodCallExpression.class);
                if (calls != null) {
                    for (PsiMethodCallExpression call : calls) {
                        PsiReferenceExpression methodExpression = call.getMethodExpression();
                        if ("super".equals(methodExpression.getReferenceName())) {
                            PsiExpressionList argumentList = call.getArgumentList();
                            if (argumentList != null && argumentList.getExpressions().length > 0) {
                                PsiExpression firstArgument = argumentList.getExpressions()[0];
                                PsiType type = firstArgument.getType();
                                if (type != null && type.getCanonicalText().equals("android.os.Looper")) {
                                    if (isMainLooper(firstArgument)) {
                                        return false;
                                    } else {
                                        return true;
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // If no constructor, or no explicit looper passed, default is main looper
            return false;
        }

        private boolean isMainLooper(PsiExpression argument) {
            if (!(argument instanceof PsiMethodCallExpression)) {
                // Default constructor uses main looper
                return true;
            }
            PsiMethodCallExpression methodCall = (PsiMethodCallExpression) argument;
            PsiReferenceExpression methodExpression = methodCall.getMethodExpression();
            String text = methodExpression.getText();
            return "Looper.getMainLooper".equals(text);
        }
    }
}
